async function search(p){p=p||{};var q=pmText(p.keyword),page=Number(p.page==null?1:p.page);if(!q)return [];if(q.length>60||!Number.isSafeInteger(page)||page<1||page>2000)throw new Error('关键词或页码无效');var data=await gpApi('/anonymous/video/searchByWordPageable',{keyword:q,pageNum:page,pageSize:20});return gpPage(data,page,'搜索');}
async function loadDetail(link){var ids=gpParse(link);return (await gpDetail(ids.id)).item;}
